{"cards": [{"node_code": "N_46c730edaefc6d5b", "definition": "研究交通基础设施在服役期间的物理状态感知、数据采集、试验检测及基于数据的安全状态评估技术，旨在实时掌握设施健康状况。", "boundary": "本节点聚焦于“感知与评估”环节，即如何获取数据并判断设施当前安全状态。边界在于区分“监测”与“管理”（基于监测数据的维护决策归入全寿命安全管理）、“监测”与“韧性”（针对灾害的恢复能力归入灾害韧性）。若内容涉及传感器硬件研发，归入本节点；若涉及监测数据的长期趋势分析与寿命预测，需结合全寿命管理判断。", "includes": ["交通设施结构健康监测（SHM）系统、传感器技术与数据采集", "交通设施无损检测、试验检测技术与标准", "基于监测数据的设施安全状态实时评估与预警"], "excludes": ["基于监测数据制定的长期维护计划与资金预算（归入全寿命安全管理）", "设施在极端灾害下的失效机理与恢复策略（归入灾害韧性）", "交通设施初始设计阶段的理论计算（非服役期监测）"], "sibling_distinctions": [{"other_code": "N_c6a8ec825f329c45", "rule": "本节点侧重“状态获取与即时评估”，即知道设施现在是否安全；全寿命安全管理侧重“基于状态的决策”，即根据评估结果决定何时修、怎么修及寿命预测。"}, {"other_code": "N_b578efc7064815f4", "rule": "本节点侧重日常或一般工况下的安全状态监测；灾害韧性侧重特定灾害场景下的风险评价与恢复能力，虽可能利用监测数据，但核心在于灾害应对。"}], "cross_boundary_rule": "当内容涉及监测数据用于寿命预测时，若侧重预测模型与算法，归入本节点（数字化安全评估）；若侧重基于预测结果的维护策略制定，归入全寿命安全管理。"}, {"node_code": "N_c6a8ec825f329c45", "definition": "研究交通基础设施从建成到报废全生命周期内的耐久性评价、性能退化规律、安全维护策略及基于状态的管理决策体系。", "boundary": "本节点聚焦于“时间维度”上的管理与决策，核心是延长设施寿命、保障长期安全。边界在于区分“管理”与“监测”（数据采集归入安全监测）、“管理”与“韧性”（灾害恢复归入灾害韧性）。若内容涉及具体的修补工艺，归入本节点（作为维护手段）；若涉及灾害后的紧急抢修，需视是否属于韧性恢复范畴。", "includes": ["交通设施耐久性评价、老化机理与寿命预测模型", "基于状态的安全维护决策、维修策略与全寿命成本分析", "交通设施全寿命周期安全管理体系与标准"], "excludes": ["实时结构健康监测传感器技术与数据采集（归入安全监测）", "针对特定自然灾害的韧性提升与恢复策略（归入灾害韧性）", "交通设施初始结构设计与施工建造技术"], "sibling_distinctions": [{"other_code": "N_46c730edaefc6d5b", "rule": "本节点侧重“决策与规划”，利用监测数据制定长期维护计划；安全监测侧重“感知与评估”，提供实时或定期的状态数据。"}, {"other_code": "N_b578efc7064815f4", "rule": "本节点侧重正常服役期内的性能保持与退化控制；灾害韧性侧重异常灾害事件下的系统恢复与抗灾能力。"}], "cross_boundary_rule": "当内容涉及设施老化与灾害损伤的耦合时，若侧重长期性能退化，归入本节点；若侧重灾害导致的突发损伤恢复，归入灾害韧性。"}, {"node_code": "N_b578efc7064815f4", "definition": "研究交通基础设施在地震、洪水、台风等自然灾害及极端事件下的风险评价、抗灾能力、失效机理及灾后快速恢复与韧性提升策略。", "boundary": "本节点聚焦于“灾害场景”下的安全与恢复，核心是设施在极端外力下的表现及恢复能力。边界在于区分“韧性”与“日常安全”（日常监测归入安全监测）、“韧性”与“全寿命管理”（长期维护归入全寿命管理）。若内容涉及灾害预警系统，归入本节点（作为韧性的一部分）；若涉及灾后救援流程，需视是否属于设施本体恢复。", "includes": ["交通设施灾害风险评价、脆弱性分析与抗灾设计", "交通设施在灾害作用下的失效机理与损伤评估", "交通基础设施灾后快速恢复、韧性提升策略与应急加固"], "excludes": ["日常工况下的结构健康监测与状态评估（归入安全监测）", "正常服役期内的耐久性评价与维护决策（归入全寿命安全管理）", "纯灾害预警技术（若未结合设施响应，可归入通用安全或气象，但结合设施韧性归入本节点）"], "sibling_distinctions": [{"other_code": "N_46c730edaefc6d5b", "rule": "本节点侧重灾害场景下的风险与恢复；安全监测侧重一般工况下的状态感知。灾害期间的监测数据服务于韧性评估，但监测技术本身归入安全监测。"}, {"other_code": "N_c6a8ec825f329c45", "rule": "本节点侧重应对突发灾害的恢复能力；全寿命管理侧重长期性能退化控制。灾害后的修复若属于恢复原状，归入本节点；若属于长期维护计划的一部分，归入全寿命管理。"}], "cross_boundary_rule": "当内容涉及灾害后的设施修复时，若侧重快速恢复交通功能的应急措施，归入本节点；若侧重修复后的长期耐久性恢复，可关联全寿命管理，但主挂载为韧性。"}]}
